   240	async function lock(db:D1Database,lid:string) { const token=id(),n=Math.floor(Date.now()/1000);const r=await db.prepare('INSERT INTO listing_locks(listing_id,token,expires_at) VALUES(?,?,?) ON CONFLICT(listing_id) DO UPDATE SET token=excluded.token,expires_at=excluded.expires_at WHERE listing_locks.expires_at < ? RETURNING token').bind(lid,token,n+3600,n).first();return r?token:null; }
   241	async function unlock(db:D1Database,lid:string,t:string) {
   242	  const correlationId=crypto.randomUUID(),attempts=3;
   243	  for(let attempt=0;attempt<attempts;attempt++){
   244	    try{await db.prepare('DELETE FROM listing_locks WHERE listing_id=? AND token=?').bind(lid,t).run();}catch{}
   245	    try{
   246	      const current=await db.prepare('SELECT token,expires_at FROM listing_locks WHERE listing_id=?').bind(lid).first<{token:string;expires_at:number}>();
   247	      if(!current||current.token!==t)return;
   248	    }catch{}
   249	  }
   250	  const nowSeconds=Math.floor(Date.now()/1000),expiredAt=nowSeconds-1;
   251	  try{await db.prepare('UPDATE listing_locks SET expires_at=? WHERE listing_id=? AND token=?').bind(expiredAt,lid,t).run();}catch{}
   252	  try{const current=await db.prepare('SELECT token,expires_at FROM listing_locks WHERE listing_id=?').bind(lid).first<{token:string;expires_at:number}>();if(!current||current.token!==t||current.expires_at<=nowSeconds){console.warn(JSON.stringify({event:'listing_lease_release_deferred_to_expiry',correlationId}));return;}}catch{}
   253	  console.error(JSON.stringify({event:'listing_lease_release_unconfirmed',correlationId,attempts}));
   254	}
