   124	  if(current.status!=='SUBMITTED')return c.json({error:'listing is no longer awaiting review'},409);
   125	  const updated=actionValue==='approve'
   126	    ? c.env.DB.prepare("UPDATE listings SET status='APPROVED',rejection_reason=NULL,updated_at=? WHERE id=? AND status='SUBMITTED' AND EXISTS (SELECT 1 FROM users WHERE users.id=listings.owner_id AND users.role='OWNER')").bind(at,listingId)
   127	    : c.env.DB.prepare("UPDATE listings SET status='REJECTED',rejection_reason=?,updated_at=? WHERE id=? AND status='SUBMITTED' AND EXISTS (SELECT 1 FROM users WHERE users.id=listings.owner_id AND users.role='OWNER')").bind(reason,at,listingId);
   128	  const audit=sourceAuditInsert(c,eventId,listingId,action,reason,at,`l.id=? AND owner.role='OWNER' AND changes()=1 AND l.status=? AND l.updated_at=?`,[listingId,status,at]);
   129	  try{
